INSERT INTO community_posts(user_id,title,body,category) SELECT id,'Welcome to the FIBIN Community','Share local food drives, pickup tips, volunteer opportunities and stories of impact. Together we can make surplus food useful.','Announcements' FROM users WHERE email='admin@fibin.org' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE title='Welcome to the FIBIN Community');
INSERT INTO community_posts(user_id,title,body,category) SELECT id,'How can I donate safely?','Keep food covered, mention preparation time, add an expiry time and coordinate pickup before posting.','Safety' FROM users WHERE email='donor@fibin.org' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE title='How can I donate safely?');
