CREATE DATABASE IF NOT EXISTS fibin_food CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fibin_food;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(50) NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('donor','receiver','admin') NOT NULL DEFAULT 'donor',bio TEXT NULL,phone VARCHAR(30) NULL,city VARCHAR(120) NULL,avatar VARCHAR(255) NULL,last_seen DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS food_donations (id INT AUTO_INCREMENT PRIMARY KEY,donor_id INT NOT NULL,title VARCHAR(180) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT 'Other',description TEXT,quantity INT NOT NULL,unit VARCHAR(30) NOT NULL DEFAULT 'servings',location VARCHAR(220) NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,expiry_date DATE NOT NULL,image VARCHAR(255) NULL,status ENUM('available','completed','expired') NOT NULL DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(donor_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_food_status(status),INDEX idx_food_coords(latitude,longitude)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS food_requests (id INT AUTO_INCREMENT PRIMARY KEY,food_id INT NOT NULL,requester_id INT NOT NULL,quantity INT NOT NULL,message TEXT,status ENUM('pending','accepted','rejected','completed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(food_id) REFERENCES food_donations(id) ON DELETE CASCADE,FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contacts (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(50) NULL UNIQUE,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS community_posts (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,category VARCHAR(50) NOT NULL DEFAULT 'General',image VARCHAR(255) NULL,likes INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS community_comments (id INT AUTO_INCREMENT PRIMARY KEY,post_id INT NOT NULL,user_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES community_posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_likes (post_id INT NOT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES community_posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS messages (id INT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,receiver_id INT NOT NULL,body TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_chat(sender_id,receiver_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS community_meetings (id INT AUTO_INCREMENT PRIMARY KEY,host_id INT NOT NULL,title VARCHAR(180) NOT NULL,meeting_url VARCHAR(500) NOT NULL,starts_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(host_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,link VARCHAR(255),is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_notifications_user(user_id,is_read)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS saved_foods (user_id INT NOT NULL,food_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,food_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(food_id) REFERENCES food_donations(id) ON DELETE CASCADE) ENGINE=InnoDB;

